const item = $input.first();
let payload = item.json;

const parseJson = (value) => {
  if (typeof value !== 'string') return value;
  const text = value.trim();
  if (!text) throw new Error('图片接口返回了空响应');
  try {
    return JSON.parse(text);
  } catch {
    throw new Error('图片接口响应不是合法 JSON');
  }
};

try {
  payload = parseJson(payload);

  for (let depth = 0; depth < 4; depth += 1) {
    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) break;
    if (payload.success !== undefined || Array.isArray(payload.files)) break;

    if (Object.prototype.hasOwnProperty.call(payload, 'body')) {
      payload = parseJson(payload.body);
      continue;
    }

    if (payload.response && typeof payload.response === 'object' && Object.prototype.hasOwnProperty.call(payload.response, 'body')) {
      payload = parseJson(payload.response.body);
      continue;
    }

    if (Object.prototype.hasOwnProperty.call(payload, 'data')) {
      const candidate = parseJson(payload.data);
      if (candidate && typeof candidate === 'object' && !Array.isArray(candidate) && (candidate.success !== undefined || candidate.data !== undefined || Array.isArray(candidate.files))) {
        payload = candidate;
        continue;
      }
    }

    break;
  }

  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('图片接口响应不是 JSON 对象');
  }

  let data;
  let code = payload.code || 'OK';
  let message = payload.message || 'ok';

  if (payload.success !== undefined) {
    if (payload.success !== true) {
      throw new Error(payload.message || payload.error?.message || '图片生成失败');
    }
    data = payload.data;
  } else if (Array.isArray(payload.files)) {
    data = payload;
  } else {
    const keys = Object.keys(payload).slice(0, 20).join(', ') || '无';
    throw new Error('未识别到图片接口响应；当前字段：' + keys + '。请确认 Code 节点连接在“调用纯生图接口”之后');
  }

  if (!data || !Array.isArray(data.files)) {
    const keys = data && typeof data === 'object' ? Object.keys(data).slice(0, 20).join(', ') : '无';
    throw new Error('图片接口响应缺少 files；data 字段：' + keys);
  }

  const files = data.files.map((file) => ({
    id: file.id ?? null,
    original_name: file.original_name ?? null,
    filename: file.filename ?? null,
    mime_type: file.mime_type ?? null,
    size_bytes: file.size_bytes ?? null,
    storage_provider: file.storage_provider ?? null,
    storage_bucket_id: file.storage_bucket_id ?? null,
    object_key: file.object_key ?? null,
    network_url: file.network_url ?? null,
    public_url: file.public_url ?? null,
    download_url: file.download_url ?? null,
    local_path: file.local_path ?? null,
    created_at: file.created_at ?? null,
  }));

  const firstFile = files[0] || {};
  return [{
    json: {
      success: true,
      code,
      message,
      provider_key: data.provider_key ?? null,
      provider_name: data.provider_name ?? null,
      operation: data.operation ?? null,
      model: data.model ?? null,
      size: data.size ?? null,
      quality: data.quality ?? null,
      output_format: data.output_format ?? null,
      image_url: firstFile.public_url || firstFile.network_url || null,
      local_path: firstFile.local_path || null,
      files,
    },
  }];
} catch (error) {
  const receivedFields = payload && typeof payload === 'object' && !Array.isArray(payload)
    ? Object.keys(payload).slice(0, 20)
    : [];
  return [{
    json: {
      success: false,
      code: payload?.code || 'INVALID_RESPONSE',
      message: error instanceof Error ? error.message : String(error),
      received_fields: receivedFields,
    },
  }];
}
